248	/// Produce the element's definition.
249	fn create(element: &Elem) -> Result<TokenStream> {
250	    // The struct itself.
251	    let struct_ = create_struct(element);
252	
253	    // Implementations.
254	    let inherent_impl = create_inherent_impl(element);
255	    let native_element_impl = create_native_elem_impl(element)?;
256	    let field_impls =
257	        element.fields.iter().map(|field| create_field_impl(element, field));
258	    let construct_impl =
259	        element.cannot("Construct").then(|| create_construct_impl(element));
260	    let set_impl = element.cannot("Set").then(|| create_set_impl(element));
261	    let mathy_impl = element.can("Mathy").then(|| create_mathy_impl(element));
262	
263	    // We use a const block to create an anonymous scope, as to not leak any
264	    // local definitions.
265	    Ok(quote! {
266	        #struct_
267	
268	        const _: () = {
269	            #inherent_impl
270	            #native_element_impl
271	            #(#field_impls)*
272	            #construct_impl
273	            #set_impl
274	            #mathy_impl
275	        };
276	    })
277	}
278	
279	/// Create the struct definition itself.
280	fn create_struct(element: &Elem) -> TokenStream {
281	    let Elem { vis, ident, docs, .. } = element;
282	
283	    let debug = element.cannot("Debug").then(|| quote! { Debug, });
284	    let fields = element.struct_fields().map(create_field);
285	    let oneliner = oneliner(docs);
286	
287	    quote! {
288	        #[doc = #oneliner]
289	        #[derive(Hash, #debug Clone)]
290	        #[expect(rustdoc::broken_intra_doc_links)]
291	        #vis struct #ident {
292	            #(#fields,)*
293	        }
294	    }
295	}
296	
297	/// Create a field declaration for the struct.
298	fn create_field(field: &Field) -> TokenStream {
299	    let Field { i, vis, ident, ty, .. } = field;
300	    if field.required {
301	        quote! { #vis #ident: #ty }
302	    } else if field.synthesized {
303	        quote! { #vis #ident: ::std::option::Option<#ty> }
304	    } else {
305	        quote! { #vis #ident: #foundations::Settable<Self, #i> }
306	    }
307	}
308	
309	/// Create the inherent implementation of the struct.
310	fn create_inherent_impl(element: &Elem) -> TokenStream {
311	    let Elem { ident, .. } = element;
312	
313	    let new_func = create_new_func(element);
314	    let with_field_methods = element.accessor_fields().map(create_with_field_method);
315	
316	    let style_consts = element.real_fields().map(|field| {
317	        let Field { i, vis, ident, .. } = field;
318	        quote! {
319	            #vis const #ident: #foundations::Field<Self, #i>
320	                = #foundations::Field::new();
321	        }
322	    });
323	
324	    quote! {
325	        impl #ident {
326	            #new_func
327	            #(#with_field_methods)*
328	        }
329	        #[expect(non_upper_case_globals)]
330	        impl #ident {
331	            #(#style_consts)*
332	        }
333	    }
334	}
335	
336	/// Create the `new` function for the element.
337	fn create_new_func(element: &Elem) -> TokenStream {
338	    let params = element
339	        .struct_fields()
340	        .filter(|field| field.required)
341	        .map(|Field { ident, ty, .. }| quote! { #ident: #ty });
342	
343	    let fields = element.struct_fields().map(|field| {
344	        let ident = &field.ident;
345	        if field.required {
346	            quote! { #ident }
347	        } else if field.synthesized {
348	            quote! { #ident: None }
349	        } else {
350	            quote! { #ident: #foundations::Settable::new() }
351	        }
352	    });
353	
354	    quote! {
355	        /// Create a new instance of the element.
356	        pub fn new(#(#params),*) -> Self {
357	            Self { #(#fields,)* }
358	        }
359	    }
360	}
361	
362	/// Create a builder-style setter method for a field.
363	fn create_with_field_method(field: &Field) -> TokenStream {
364	    let Field { vis, ident, with_ident, name, ty, .. } = field;
365	    let doc = format!("Builder-style setter for the [`{name}`](Self::{ident}) field.");
366	
367	    let expr = if field.required {
368	        quote! { self.#ident = #ident }
369	    } else if field.synthesized {
370	        quote! { self.#ident = Some(#ident) }
371	    } else {
372	        quote! { self.#ident.set(#ident) }
373	    };
374	
375	    quote! {
376	        #[doc = #doc]
377	        #vis fn #with_ident(mut self, #ident: #ty) -> Self {
378	            #expr;
379	            self
380	        }
381	    }
382	}
383	
384	/// Creates the element's `NativeElement` implementation.
385	fn create_native_elem_impl(element: &Elem) -> Result<TokenStream> {
386	    let Elem {
387	        name, ident, title, since, scope, keywords, docs, ..
388	    } = element;
389	    let def_site_key = ident.to_string();
390	
391	    let since = if let Some(since) = since {
392	        quote! { Some(#since) }
393	    } else {
394	        quote! { None }
395	    };
396	
397	    let fields = element.fields.iter().filter(|field| !field.internal).map(|field| {
398	        let i = field.i;
399	        if field.external {
400	            quote! { #foundations::ExternalFieldData::<#ident, #i>::vtable() }
401	        } else if field.variadic {
402	            quote! { #foundations::RequiredFieldData::<#ident, #i>::vtable_variadic() }
403	        } else if field.required {
404	            quote! { #foundations::RequiredFieldData::<#ident, #i>::vtable() }
405	        } else if field.synthesized {
406	            quote! { #foundations::SynthesizedFieldData::<#ident, #i>::vtable() }
407	        } else if field.ghost {
408	            quote! { #foundations::SettablePropertyData::<#ident, #i>::vtable() }
409	        } else {
410	            quote! { #foundations::SettableFieldData::<#ident, #i>::vtable() }
411	        }
412	    });
413	
414	    let field_arms = element
415	        .fields
416	        .iter()
417	        .filter(|field| !field.internal && !field.external)
418	        .map(|field| {
419	            let Field { name, i, .. } = field;
420	            quote! { #name => Some(#i) }
421	        });
422	    let field_id = quote! {
423	        |name| match name {
424	            #(#field_arms,)*
425	            _ => None,
426	        }
427	    };
428	
429	    let capable_func = create_capable_func(element);
430	    let introspection = create_introspection_capabilities(element)?;
431	
432	    let with_keywords =
433	        (!keywords.is_empty()).then(|| quote! { .with_keywords(&[#(#keywords),*]) });
434	    let with_repr = element.can("Repr").then(|| quote! { .with_repr() });
435	    let with_partial_eq = element.can("PartialEq").then(|| quote! { .with_partial_eq() });
436	    let with_local_name = element.can("LocalName").then(|| quote! { .with_local_name() });
437	    let with_scope = scope.then(|| quote! { .with_scope() });
438	
439	    Ok(quote! {
440	        unsafe impl #foundations::NativeElement for #ident {
441	            const ELEM: #foundations::Element = #foundations::Element::from_vtable({
442	                static STORE: #foundations::LazyElementStore
443	                    = #foundations::LazyElementStore::new();
444	                static VTABLE: #foundations::ContentVtable =
445	                    #foundations::ContentVtable::new::<#ident>(
446	                        #name,
447	                        #title,
448	                        #since,
449	                        #docs,
450	                        ::typst_utils::DefSite { path: file!(), key: #def_site_key },
451	                        &[#(#fields),*],
452	                        #field_id,
453	                        #capable_func,
454	                        #introspection,
455	                        || &STORE,
456	                    ) #with_keywords
457	                    #with_repr
458	                    #with_partial_eq
459	                    #with_local_name
460	                    #with_scope
461	                    .erase();
462	                &VTABLE
463	            });
464	        }
465	    })
466	}
