468	/// Creates the appropriate trait implementation for a field.
469	fn create_field_impl(element: &Elem, field: &Field) -> TokenStream {
470	    let elem_ident = &element.ident;
471	    let Field { i, ty, ident, default, positional, name, docs, .. } = field;
472	    let def_site_key = format!("{elem_ident}::{ident}");
473	    let def_site = quote! {
474	        ::typst_utils::DefSite { path: file!(), key: #def_site_key }
475	    };
476	
477	    let default = match default {
478	        Some(default) => quote! { || #default },
479	        None => quote! { std::default::Default::default },
480	    };
481	
482	    if field.external {
483	        quote! {
484	            impl #foundations::ExternalField<#i> for #elem_ident {
485	                type Type = #ty;
486	                const FIELD: #foundations::ExternalFieldData<Self, #i> =
487	                    #foundations::ExternalFieldData::<Self, #i>::new(
488	                        #name,
489	                        #docs,
490	                        #def_site,
491	                        #default,
492	                    );
493	            }
494	        }
495	    } else if field.required {
496	        quote! {
497	            impl #foundations::RequiredField<#i> for #elem_ident {
498	                type Type = #ty;
499	                const FIELD: #foundations::RequiredFieldData<Self, #i> =
500	                    #foundations::RequiredFieldData::<Self, #i>::new(
501	                        #name,
502	                        #docs,
503	                        #def_site,
504	                        |elem| &elem.#ident,
505	                    );
506	            }
507	        }
508	    } else if field.synthesized {
509	        quote! {
510	            impl #foundations::SynthesizedField<#i> for #elem_ident {
511	                type Type = #ty;
512	                const FIELD: #foundations::SynthesizedFieldData<Self, #i> =
513	                    #foundations::SynthesizedFieldData::<Self, #i>::new(
514	                        #name,
515	                        #docs,
516	                        #def_site,
517	                        |elem| &elem.#ident,
518	                    );
519	            }
520	        }
521	    } else {
522	        let slot = quote! {
523	            || {
524	                static LOCK: ::std::sync::OnceLock<#ty> = ::std::sync::OnceLock::new();
525	                &LOCK
526	            }
527	        };
528	
529	        let with_fold = field.fold.then(|| quote! { .with_fold() });
530	        let refable = (!field.fold).then(|| {
531	            quote! {
532	                impl #foundations::RefableProperty<#i> for #elem_ident {}
533	            }
534	        });
535	
536	        if field.ghost {
537	            quote! {
538	                impl #foundations::SettableProperty<#i> for #elem_ident {
539	                    type Type = #ty;
540	                    const FIELD: #foundations::SettablePropertyData<Self, #i> =
541	                        #foundations::SettablePropertyData::<Self, #i>::new(
542	                            #name,
543	                            #docs,
544	                            #def_site,
545	                            #positional,
546	                            #default,
547	                            #slot,
548	                        ) #with_fold;
549	                }
550	                #refable
551	            }
552	        } else {
553	            quote! {
554	                impl #foundations::SettableField<#i> for #elem_ident {
555	                    type Type = #ty;
556	                    const FIELD: #foundations::SettableFieldData<Self, #i> =
557	                        #foundations::SettableFieldData::<Self, #i>::new(
558	                            #name,
559	                            #docs,
560	                            #def_site,
561	                            #positional,
562	                            |elem| &elem.#ident,
563	                            |elem| &mut elem.#ident,
564	                            #default,
565	                            #slot,
566	                        ) #with_fold;
567	                }
568	                #refable
569	            }
570	        }
571	    }
572	}
573	
574	/// Creates the element's `Construct` implementation.
575	fn create_construct_impl(element: &Elem) -> TokenStream {
576	    let ident = &element.ident;
577	    let setup = element.construct_fields().map(|field| {
578	        let (prefix, value) = create_field_parser(field);
579	        let ident = &field.ident;
580	        quote! {
581	            #prefix
582	            let #ident = #value;
583	        }
584	    });
585	
586	    let fields = element.struct_fields().map(|field| {
587	        let ident = &field.ident;
588	        if field.required {
589	            quote! { #ident }
590	        } else if field.synthesized {
591	            quote! { #ident: None }
592	        } else {
593	            quote! { #ident: #foundations::Settable::from(#ident) }
594	        }
595	    });
596	
597	    quote! {
598	        impl #foundations::Construct for #ident {
599	            fn construct(
600	                engine: &mut ::typst_library::engine::Engine,
601	                args: &mut #foundations::Args,
602	            ) -> ::typst_library::diag::SourceResult<#foundations::Content> {
603	                #(#setup)*
604	                Ok(#foundations::Content::new(Self { #(#fields),* }))
605	            }
606	        }
607	    }
608	}
609	
610	/// Creates the element's `Set` implementation.
611	fn create_set_impl(element: &Elem) -> TokenStream {
612	    let ident = &element.ident;
613	    let handlers = element.set_fields().map(|field| {
614	        let field_ident = &field.ident;
615	        let (prefix, value) = create_field_parser(field);
616	        quote! {
617	            #prefix
618	            if let Some(value) = #value {
619	                styles.set(Self::#field_ident, value);
620	            }
621	        }
622	    });
623	
624	    quote! {
625	        impl #foundations::Set for #ident {
626	            fn set(
627	                engine: &mut ::typst_library::engine::Engine,
628	                args: &mut #foundations::Args,
629	            ) -> ::typst_library::diag::SourceResult<#foundations::Styles> {
630	                let mut styles = #foundations::Styles::new();
631	                #(#handlers)*
632	                Ok(styles)
633	            }
634	        }
635	    }
636	}
637	
638	/// Create argument parsing code for a field.
639	fn create_field_parser(field: &Field) -> (TokenStream, TokenStream) {
640	    if let Some(BlockWithReturn { prefix, expr }) = &field.parse {
641	        return (quote! { #(#prefix);* }, quote! { #expr });
642	    }
643	
644	    let name = &field.name;
645	    let value = if field.variadic {
646	        quote! { args.all()? }
647	    } else if field.required {
648	        quote! { args.expect(#name)? }
649	    } else if field.positional {
650	        quote! { args.find()? }
651	    } else {
652	        quote! { args.named(#name)? }
653	    };
654	
655	    (quote! {}, value)
656	}
657	
658	/// Creates the element's casting vtable.
659	fn create_capable_func(element: &Elem) -> TokenStream {
660	    // Forbidden capabilities, i.e capabilities that are not object safe or
661	    // introspection capabilities that are handled otherwise.
662	    const FORBIDDEN: &[&str] = &[
663	        // Not object safe.
664	        "Debug",
665	        "PartialEq",
666	        "Hash",
667	        "Construct",
668	        "Set",
669	        "Repr",
670	        "LocalName",
671	        // Introspection capabilities.
672	        "Locatable",
673	        "Unqueriable",
674	        "Tagged",
675	    ];
676	
677	    let ident = &element.ident;
678	    let relevant = element
679	        .capabilities
680	        .iter()
681	        .filter(|&ident| !FORBIDDEN.contains(&(&ident.to_string() as &str)));
682	
683	    let checks = relevant.map(|capability| {
684	        quote! {
685	            if capability == ::std::any::TypeId::of::<dyn #capability>() {
686	                // Safety: The vtable function doesn't require initialized
687	                // data, so it's fine to use a dangling pointer.
688	                return Some(unsafe {
689	                    ::typst_utils::fat::vtable(dangling as *const dyn #capability)
690	                });
691	            }
692	        }
693	    });
694	
695	    quote! {
696	        |capability| {
697	            let dangling = ::std::ptr::NonNull::<#foundations::Packed<#ident>>::dangling().as_ptr();
698	            #(#checks)*
699	            None
700	        }
701	    }
702	}
703	
704	/// Creates the element's casting vtable.
705	fn create_introspection_capabilities(element: &Elem) -> Result<TokenStream> {
706	    let find_cap = |name| element.capabilities.iter().find(|ident| *ident == name);
707	    let locatable = find_cap("Locatable");
708	    let unqueriable = find_cap("Unqueriable");
709	    let tagged = find_cap("Tagged");
710	
711	    if let Some(unqueriable) = unqueriable
712	        && locatable.is_none()
713	    {
714	        bail!(unqueriable, "only `Locatable` element can be marked `Unqueriable`");
715	    }
716	
717	    let locatable = locatable.is_some();
718	    let unqueriable = unqueriable.is_some();
719	    let tagged = tagged.is_some();
720	    Ok(quote! {
721	        #foundations::IntrospectionCapabilities {
722	            locatable: #locatable,
723	            unqueriable: #unqueriable,
724	            tagged: #tagged,
725	        }
726	    })
727	}
728	
729	/// Creates the element's `Mathy` implementation.
730	fn create_mathy_impl(element: &Elem) -> TokenStream {
731	    let ident = &element.ident;
732	    quote! { impl ::typst_library::math::Mathy for #foundations::Packed<#ident> {} }
733	}
